#!/usr/bin/env bash
# Check (or fix) the whitespace formatting of the C# code of the game against .editorconfig: braces on a new line,
# indents, spaces, the encoding (charset = utf-8, no BOM).
#
# Scope: client/Assets (without Plugins), shared, backend. Not checked: tools/framework (its formatting is a change of
# the framework, made there), client/Packages, bin/obj, generated code (*.g.cs and files with an <auto-generated/> header
# are skipped by dotnet format itself).
#
# `dotnet format whitespace --folder`: the files come from the folders, not from the projects. The set is the same as
# through client/client.sln + backend/backend.slnx (checked on 2026-11-25: 801 files of the scope with findings in both),
# but the check needs no Unity-generated csproj (absent in CI and in a snapshot without Unity), no restore and runs in
# seconds. Only whitespace: `dotnet format style` changes code (the style rules of .editorconfig are suggestions) and
# needs a compilation.
#
# Usage:
#   tools/scripts/check-format.sh                # verify the whole scope; exit 1 and a short list on violations
#   tools/scripts/check-format.sh --fix          # format the scope in place
#   tools/scripts/check-format.sh --backend      # only backend + shared (the scope of the CI of the backend)
#   tools/scripts/check-format.sh --framework    # verify tools/framework instead (a count for the framework; not a gate)
#
# Exit code: 0 clean (or fixed), 1 violations, 2 bad arguments, other: dotnet format failed.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

FIX=0
SCOPE=game

usage() {
    sed -n '2,/^set -euo/p' "${BASH_SOURCE[0]}" | sed '$d' | sed 's/^# \{0,1\}//'
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --fix) FIX=1 ;;
        --backend) SCOPE=backend ;;
        --framework) SCOPE=framework ;;
        -h|--help) usage; exit 0 ;;
        *) echo "Unknown argument: $1" >&2; usage >&2; exit 2 ;;
    esac
    shift
done
if [[ "$FIX" == "1" && "$SCOPE" == "framework" ]]; then
    echo "--fix --framework: the framework is formatted in its own repository, not from a game" >&2
    exit 2
fi

case "$SCOPE" in
    game) include=(client/Assets/ shared/ backend/) ;;
    backend) include=(shared/ backend/) ;;
    framework) include=(tools/framework/) ;;
esac
exclude=(client/Assets/Plugins/ client/Packages/ '**/bin/' '**/obj/')
if [[ "$SCOPE" != "framework" ]]; then
    exclude+=(tools/)
fi

args=(whitespace . --folder --include "${include[@]}" --exclude "${exclude[@]}")

cd "$ROOT"

if [[ "$FIX" == "1" ]]; then
    dotnet format "${args[@]}"
    echo "Formatted: ${include[*]}"
    exit 0
fi

out="$(mktemp)"
trap 'rm -f "$out"' EXIT
code=0
dotnet format "${args[@]}" --verify-no-changes >"$out" 2>&1 || code=$?

if [[ $code -eq 0 ]]; then
    echo "Formatting OK: ${include[*]}"
    exit 0
fi
# 2 = files would change; anything else is a failure of the tool.
if [[ $code -ne 2 ]]; then
    cat "$out" >&2
    echo "dotnet format failed (exit $code)" >&2
    exit "$code"
fi

# Lines: <abs path>(<line>,<col>): error <ID>: <message> [<workspace>]
violations="$(grep -E ': error (WHITESPACE|CHARSET|FINALNEWLINE)' "$out" | sed -E "s|^$ROOT/||; s| \[[^]]*\]$||; s|: error |: |")"
files="$(sed -E 's/\(.*//' <<<"$violations" | sort -u)"
echo "Formatting violations: $(wc -l <<<"$violations") in $(wc -l <<<"$files") files"
head -40 <<<"$violations"
if [[ $(wc -l <<<"$violations") -gt 40 ]]; then
    echo "... (first 40 shown)"
fi
echo "Files:"
sed 's/^/  /' <<<"$files" | head -40
if [[ "$SCOPE" != "framework" ]]; then
    echo "Fix: tools/scripts/check-format.sh --fix"
fi
exit 1
